using Microsoft.AspNetCore.Identity;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using MyDoc.Models;using System.ComponentModel.DataAnnotations;namespace MyDoc.Pages.Account;public sealed class RegisterModel(UserManager<ApplicationUser> users,SignInManager<ApplicationUser> signIn):PageModel{[BindProperty]public InputModel Input{get;set;}=new();public sealed class InputModel{[Required,StringLength(100)]public string FullName{get;set;}="";[Required,EmailAddress]public string Email{get;set;}="";[Required,DataType(DataType.Password),StringLength(100,MinimumLength=8)]public string Password{get;set;}="";[Required,DataType(DataType.Password),Compare(nameof(Password))]public string ConfirmPassword{get;set;}="";}public void OnGet(){}public async Task<IActionResult>OnPostAsync(){if(!ModelState.IsValid)return Page();var user=new ApplicationUser{FullName=Input.FullName.Trim(),Email=Input.Email.Trim(),UserName=Input.Email.Trim()};var result=await users.CreateAsync(user,Input.Password);if(result.Succeeded){await signIn.SignInAsync(user,false);return RedirectToPage("/Index");}foreach(var e in result.Errors)ModelState.AddModelError(string.Empty,e.Description);return Page();}}
